from pathlib import Path
import json,subprocess,sys
p=Path('products/invoice-preflight'); existing=list(p.rglob('*')) if p.exists() else []
print('Existing prototype files:',[str(x) for x in existing if x.is_file()][:100])
p.mkdir(parents=True,exist_ok=True)
name=p/'csv_structure_check.py'
code='''import csv, io, json, sys

def check(text):
    issues=[]
    try:
        rows=list(csv.reader(io.StringIO(text.lstrip("\\ufeff")),strict=True))
    except csv.Error as exc:
        return {"issues":[{"kind":"invalid_csv","detail":str(exc)}],"data_rows":0}
    if not rows:
        return {"issues":[{"kind":"empty_file"}],"data_rows":0}
    headers=rows[0]
    if any(not h.strip() for h in headers): issues.append({"kind":"blank_header"})
    normalized=[h.strip().casefold() for h in headers]
    if len(set(normalized))!=len(normalized): issues.append({"kind":"duplicate_header"})
    for line,row in enumerate(rows[1:],2):
        if len(row)!=len(headers): issues.append({"kind":"column_count","record":line,"expected":len(headers),"actual":len(row)})
    return {"issues":issues,"data_rows":len(rows)-1,"columns":len(headers)}

if __name__=="__main__":
    with open(sys.argv[1],encoding="utf-8",newline="") as source: result=check(source.read())
    print(json.dumps(result,indent=2))
    sys.exit(1 if result["issues"] else 0)
'''
if name.exists():
 print('Existing checker preserved; contents:'); print(name.read_text()[:18000]); sys.exit(0)
name.write_text(code)
ns={'__name__':'test_module'}; exec(compile(code,str(name),'exec'),ns); check=ns['check']
cases=[('quoted multiline','Invoice,Description\n1,"hello\nworld"\n',[]),('bom','\ufeffInvoice,Total\n1,12.50\n',[]),('ragged','Invoice,Total\n1\n',['column_count']),('duplicates','Invoice, invoice \n1,2\n',['duplicate_header']),('empty','',['empty_file']),('malformed','Invoice,Note\n1,"unfinished',['invalid_csv'])]
results=[]
for label,text,expected in cases:
 actual=[x['kind'] for x in check(text)['issues']]; results.append({'case':label,'passed':actual==expected,'expected':expected,'actual':actual})
(p/'structure-test-results.json').write_text(json.dumps(results,indent=2))
(p/'sample.csv').write_text('Invoice,Customer,Total\nDEMO-001,Example customer,12.50\n')
(p/'STRUCTURE-CHECK.md').write_text('# Local CSV structure check\n\nRun: python3 products/invoice-preflight/csv_structure_check.py products/invoice-preflight/sample.csv\n\nChecks comma-separated UTF-8 CSV syntax, blank or duplicate headers and inconsistent record widths. Runs locally using the Python standard library. Multiline quoted fields and UTF-8 BOM are supported.\n\nThis is a generic structural check. It does not validate invoice amounts, tax, customer mappings, required platform fields or successful import into Manager or any accounting platform. Passing does not establish import compatibility. No payment or revenue has been verified.\n')
print(json.dumps(results,indent=2)); assert all(x['passed'] for x in results)
